<script setup lang="ts">
import { computed, ref } from 'vue'; import { storeToRefs } from 'pinia'; import { onBeforeRouteLeave, useRoute, useRouter } from 'vue-router'; import PageHeader from '@/Components/layout/PageHeader.vue'; import MissionForm from '@/Components/missions/MissionForm.vue'; import { useAdministratorStore } from '@/stores/administrator.store'; import { useUiFeedbackStore } from '@/stores/ui-feedback.store'; import type { MissionInput } from '@/types/administrator'
const route = useRoute(); const router = useRouter(); const store = useAdministratorStore(); const feedback = useUiFeedbackStore(); const { sites, users, teams } = storeToRefs(store); const id = computed(() => route.params.missionId as string | undefined); const mission = computed(() => id.value ? store.getMissionById(id.value) : undefined); const dirty = ref(false)
onBeforeRouteLeave(async () => !dirty.value || await feedback.askConfirmation({ title: 'Quitter sans enregistrer ?', message: 'Les modifications de cette mission seront perdues.', confirmText: 'Quitter' }))
function submit(payload: MissionInput) { dirty.value = false; const missionId = id.value ? (store.updateMission(id.value, payload), id.value) : store.createMission(payload); feedback.success(id.value ? 'Mission mise à jour.' : 'Mission planifiée.'); void router.push({ name: 'admin-mission-details', params: { missionId } }) }
</script>
<template><div class="mx-auto w-full max-w-[1050px]"><PageHeader><template #title>{{ id ? 'Modifier la mission' : 'Nouvelle mission' }}</template><template #description>Configurez la période, le site et l’équipe affectée.</template><template #actions><v-btn variant="text" prepend-icon="mdi-arrow-left" :to="{ name: 'admin-missions' }">Retour</v-btn></template></PageHeader><v-alert v-if="id && !mission" type="error" variant="tonal" title="Mission introuvable" /><MissionForm v-else :mission="mission" :sites="sites" :users="users" :teams="teams" @submit="submit" @cancel="router.back()" @dirty-change="dirty = $event" /></div></template>
